// Business-model verdict per project: user-owned file under the pm dir
// { <slug>: { verdict, note, at } }. Written by the project page (or an idea-research
// session), never generated by pm itself — pm runs no LLM.
import { readFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { PM_ROOT } from "./paths.mjs";
import { writeJson } from "./relay.mjs";

export const VERDICTS = ["yes", "maybe", "no", "personal", "public"];
export const NOTE_MAX = 600;
const SLUG_RE = /^[a-z0-9][a-z0-9_-]*$/;
const dir = (root) => join(root, ".claude", "pm");
const file = (root) => join(dir(root), "business.json");

function readAll(root) {
  try {
    const raw = JSON.parse(readFileSync(file(root), "utf8"));
    return raw && typeof raw === "object" && !Array.isArray(raw) ? raw : {};
  } catch {
    return {};
  }
}

export function readBusiness(slug, root = PM_ROOT) {
  const all = readAll(root);
  const v = Object.hasOwn(all, slug) ? all[slug] : null;
  return v && VERDICTS.includes(v.verdict) ? { verdict: v.verdict, note: String(v.note || ""), at: v.at || null } : null;
}

// verdict null clears it. Throws {status:400} on bad input.
export function setBusiness(slug, verdict, note = "", root = PM_ROOT) {
  const bad = (m) => Object.assign(new Error(m), { status: 400 });
  if (!SLUG_RE.test(slug || "") || slug === "ideas") throw bad("bad slug");
  const all = readAll(root);
  if (verdict === null) delete all[slug];
  else {
    if (!VERDICTS.includes(verdict)) throw bad("bad verdict");
    if (typeof note !== "string" || note.length > NOTE_MAX || /[\u0000-\u0008\u000b-\u001f]/.test(note)) throw bad("bad note");
    all[slug] = { verdict, note: note.trim(), at: new Date().toISOString().slice(0, 10) };
  }
  mkdirSync(dir(root), { recursive: true });
  writeJson(file(root), all);
  return readBusiness(slug, root);
}
